import { Match as M, Schema as S } from "effect";
import type { Command } from "foldkit";
import { Submodel } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { m } from "foldkit/message";
import { evo } from "foldkit/struct";

import * as NativeSelect from "../../ui/native-select";

// MODEL

export const Model = S.Struct({
  status: S.String,
});
export type Model = typeof Model.Type;

// MESSAGE

export const ChangedStatus = m("ChangedStatus", { value: S.String });
export const Message = S.Union([ChangedStatus]);
export type Message = typeof Message.Type;

// INIT

export const init = (): readonly [
  Model,
  readonly Command.Command<Message>[],
] => [{ status: "todo" }, []];

// UPDATE

export const update = (
  model: Model,
  message: Message
): readonly [Model, readonly Command.Command<Message>[]] =>
  M.value(message).pipe(
    M.withReturnType<readonly [Model, readonly Command.Command<Message>[]]>(),
    M.tagsExhaustive({
      ChangedStatus: ({ value }) => [evo(model, { status: () => value }), []],
    })
  );

// VIEW

const statusOptions: readonly NativeSelect.OptionConfig[] = [
  { value: "todo", label: "مهام" },
  { value: "in-progress", label: "قيد التنفيذ" },
  { value: "done", label: "منجز" },
  { value: "cancelled", label: "ملغي" },
];

export const view = Submodel.defineView<Model, Message>((model): Html => {
  const h = html<Message>();

  return h.div(
    [h.Dir("rtl")],
    [
      NativeSelect.rootView<Message>({
        children: [
          NativeSelect.labelView<Message>({
            forId: "status-rtl",
            children: [h.span([], ["اختر الحالة"])],
          }),
          NativeSelect.triggerView<Message>({
            id: "status-rtl",
            value: model.status,
            onChange: (value) => ChangedStatus({ value }),
            options: statusOptions,
          }),
        ],
      }),
    ]
  );
});

import { Scene } from "foldkit";
import { describe, test } from "vitest";

import * as Example from "./main";

describe("Native Select RTL example", () => {
  test("renders right-to-left status options and updates value", () => {
    Scene.scene(
      { update: Example.update, view: Example.view },
      Scene.with(Example.init()[0]),
      Scene.expect(Scene.role("combobox", { name: "اختر الحالة" })).toExist(),
      Scene.expect(Scene.text("مهام")).toExist(),
      Scene.expect(Scene.text("قيد التنفيذ")).toExist(),
      Scene.expect(Scene.text("منجز")).toExist(),
      Scene.change(Scene.role("combobox", { name: "اختر الحالة" }), "done"),
      Scene.expect(Scene.role("combobox", { name: "اختر الحالة" })).toHaveValue(
        "done"
      )
    );
  });
});
